import ee, math, sys
ee.Initialize(project='earthsense-436113')

# 1. Geometry & Time Definitions
lon, lat = 157.706220, -34.344553
region = ee.Geometry.Point([lon, lat]).buffer(100000)  # 100 km

p1_start, p1_end = '2018-11-01', '2019-03-01'
p2_start, p2_end = '2019-11-01', '2020-03-01'

scale = 30000  # coarse model grid; large scale for efficiency

# 2. Choose dataset and band (auto-detect BC AOD band)
def choose_dataset_and_band():
    ds_candidates = [
        'ECMWF/CAMS/REANALYSIS_EAC4',
        'ECMWF/CAMS/REANALYSIS',
        'ECMWF/CAMS/NRT'
    ]
    band_candidates = [
        'aod550_blackcarbon','aod550bc','bcaod550',
        'aod550_black_carbon','aod550blackcarbon'
    ]
    for ds in ds_candidates:
        try:
            col = ee.ImageCollection(ds).filterDate('2019-01-01', '2019-02-01')
            if col.size().getInfo() == 0:
                continue
            # try explicit candidates first
            first_img = ee.Image(col.first())
            band_names = first_img.bandNames().getInfo()
            # exact candidates
            for b in band_candidates:
                if b in band_names:
                    return ds, b
            # heuristic: any band containing both 'aod' and ('bc' or 'black')
            chosen = None
            for b in band_names:
                bl = b.lower()
                if ('aod' in bl) and (('bc' in bl) or ('black' in bl)):
                    chosen = b
                    break
            if chosen:
                return ds, chosen
        except Exception:
            continue
    return None, None

dataset_id, band = choose_dataset_and_band()
if not dataset_id or not band:
    print("Dataset or band not found.")
    print("D")
    sys.exit(0)

print(f"Dataset: {dataset_id} band={band}")
print(f"Region: ({lat:.4f}, {lon:.4f}), r=100km")

def period_stats(start, end):
    try:
        col = ee.ImageCollection(dataset_id).filterDate(start, end).select([band])
        size = col.size().getInfo()
    except Exception as e:
        print(f"Collection error: {e}")
        return {'status': 'D'}
    if size == 0:
        return {'status': 'C1'}
    try:
        img = col.mean().rename('bc_aod')
        # count valid pixels (unmasked)
        count = img.reduceRegion(
            reducer=ee.Reducer.count(),
            geometry=region,
            scale=scale,
            maxPixels=1e9,
            bestEffort=True
        ).get('bc_aod').getInfo()
        if (count is None) or (int(count) == 0):
            return {'status': 'C2'}
        val = img.reduceRegion(
            reducer=ee.Reducer.mean(),
            geometry=region,
            scale=scale,
            maxPixels=1e9,
            bestEffort=True
        ).get('bc_aod').getInfo()
    except Exception as e:
        print(f"Processing error: {e}")
        return {'status': 'D'}
    # validate result range
    if (val is None) or (isinstance(val, float) and (math.isnan(val) or val < 0 or val > 5)):
        return {'status': 'C3'}
    return {'status': 'OK', 'val': float(val), 'count': int(count), 'nimg': int(size)}

# 3. Compute stats
s1 = period_stats(p1_start, p1_end)
s2 = period_stats(p2_start, p2_end)

# 4. Handle failure cases
for s in (s1, s2):
    if s['status'] in ['D', 'C1', 'C2', 'C3']:
        print(f"Status: {s['status']}")
        print(s['status'])
        sys.exit(0)

# 5. Report and comparison
print(f"{p1_start[:7]}..{p1_end[:7]} Images: {s1['nimg']} | mean: {s1['val']:.4f} | pix: {s1['count']}")
print(f"{p2_start[:7]}..{p2_end[:7]} Images: {s2['nimg']} | mean: {s2['val']:.4f} | pix: {s2['count']}")
delta = s2['val'] - s1['val']
pct = (delta / s1['val'] * 100.0) if s1['val'] != 0 else float('inf')
print(f"Delta: {delta:.4f} ({pct:.1f}%)")

# 6. Final Answer
if delta > 0:
    print("A")
else:
    print("B")

