import ee, math, sys
ee.Initialize(project='earthsense-436113')

# 1. Geometry & Time Definitions
lon, lat = 157.706220, -34.344553
region = ee.Geometry.Point([lon, lat]).buffer(100000)  # 100 km
p1_start, p1_end = '2018-11-01', '2019-03-01'
p2_start, p2_end = '2019-11-01', '2020-03-01'
scale = 30000  # coarse grid scale

# 2. Dataset and band discovery
ds_candidates = [
    'ECMWF/CAMS/REANALYSIS_EAC4',
    'ECMWF/CAMS/REANALYSIS',
    'ECMWF/CAMS/NRT'
]
band_candidates = [
    'aod550_black_carbon', 'aod550_blackcarbon', 'bcaod550', 'aod550bc',
    'black_carbon_aod550', 'aod550_black_carbon_optical_depth'
]

def get_band(ds):
    try:
        any_img = ee.Image(ee.ImageCollection(ds).first())
        names = any_img.bandNames().getInfo() or []
    except Exception:
        return None
    # exact candidates first
    for b in band_candidates:
        if b in names:
            return b
    # heuristic
    for b in names:
        bl = b.lower()
        if ('aod' in bl) and (('black' in bl) or ('bc' in bl)):
            return b
    return None

# pick a dataset that has data for both periods and a BC AOD band
chosen_ds, chosen_band = None, None
for ds in ds_candidates:
    b = get_band(ds)
    if not b:
        continue
    try:
        n1 = ee.ImageCollection(ds).filterDate(p1_start, p1_end).size().getInfo()
        n2 = ee.ImageCollection(ds).filterDate(p2_start, p2_end).size().getInfo()
    except Exception:
        continue
    if (n1 > 0) and (n2 > 0):
        chosen_ds, chosen_band = ds, b
        break

if not chosen_ds or not chosen_band:
    print("Dataset/band not available for both periods.")
    print("C1")
    sys.exit(0)

print(f"Dataset: {chosen_ds} | band: {chosen_band}")
print(f"Region: (-34.3446, 157.7062), r=100km")

def period_stats(start, end):
    try:
        col = ee.ImageCollection(chosen_ds).filterDate(start, end).select([chosen_band])
        size = col.size().getInfo()
        if size == 0:
            return {'status': 'C1'}
        img = col.mean().rename('bc_aod')
        count = img.reduceRegion(
            reducer=ee.Reducer.count(),
            geometry=region,
            scale=scale,
            maxPixels=1e9,
            bestEffort=True
        ).get('bc_aod').getInfo()
        if (count is None) or int(count) == 0:
            return {'status': 'C2'}
        val = img.reduceRegion(
            reducer=ee.Reducer.mean(),
            geometry=region,
            scale=scale,
            maxPixels=1e9,
            bestEffort=True
        ).get('bc_aod').getInfo()
    except Exception as e:
        print(f"Processing error: {str(e)[:120]}")
        return {'status': 'D'}
    if (val is None) or (isinstance(val, float) and (math.isnan(val) or val < 0 or val > 5)):
        return {'status': 'C3'}
    return {'status': 'OK', 'val': float(val), 'count': int(count), 'nimg': int(size)}

s1 = period_stats(p1_start, p1_end)
s2 = period_stats(p2_start, p2_end)

for s in (s1, s2):
    if s['status'] != 'OK':
        print(s['status'])
        sys.exit(0)

print(f"{p1_start[:7]}..{p1_end[:7]} Images: {s1['nimg']} | mean: {s1['val']:.5f} | pix: {s1['count']}")
print(f"{p2_start[:7]}..{p2_end[:7]} Images: {s2['nimg']} | mean: {s2['val']:.5f} | pix: {s2['count']}")

delta = s2['val'] - s1['val']
pct = (delta / s1['val'] * 100.0) if s1['val'] != 0 else float('inf')
print(f"Delta: {delta:.5f} ({'inf' if pct==float('inf') else f'{pct:.1f}%'}))")

# Final answer
if delta > 0:
    print("A")
else:
    print("B")
